library IEEE;
use ieee.std_logic_1164.all;
use WORK.constants.all;
use ieee.numeric_std.all;

-- Implementation using carry select adders, PIPELINED version
-- One pipeline register stage per Booth layer (max throughput)
--
-- EN            : external stall signal coming from the rest of the datapath.
--                 When '1' the pipeline may advance (subject to reg_en below),
--                 when '0' every pipeline register holds its value regardless
--                 of the internal FSM state.
-- START         : pulses for exactly one cycle, generated by the encoder in
--                 the EX stage, when a MUL instruction enters the multiplier.
-- BUSY          : high for the whole duration of a multiplication (internally
--                 managed by the FSM below), used by the hazard unit to stall
--                 the following instructions.
-- DONE          : pulses for exactly one cycle, the same cycle RES becomes
--                 valid, so it is perfectly aligned with the data pipeline.
--
-- No overlap between multiplications is supported: the hazard unit must not
-- issue a new START while BUSY = '1'.
entity BOOTHMUL_pipelined is
    generic(
        NBIT : integer := numBit);
    port(
        CLK : in std_logic;
        RST : in std_logic;                    -- asynchronous reset, active low
        EN  : in std_logic;                    -- global pipeline enable / stall
        A : in std_logic_vector(NBIT-1 downto 0);
        B : in std_logic_vector(NBIT-1 downto 0);
        RES : out std_logic_vector(NBIT-1 downto 0);

        START : in  std_logic;                 -- 1-cycle pulse: new MUL entering the pipeline
        BUSY  : out std_logic;                 -- high while a multiplication is in flight
        DONE  : out std_logic                  -- 1-cycle pulse: RES is valid this cycle
    );
end entity;

architecture STRUCTURAL of BOOTHMUL_pipelined is 

-- shifter of 1 bit left : used to multiply a signal by 2
    component LSL
        generic(NBIT: integer :=NBIT);
        port(
            A : in std_logic_vector(NBIT-1 downto 0);
            Y : out std_logic_vector(NBIT-1 downto 0)
        );
    end component;

-- shifter of 2 bit left : used to multiply a signal by 4
    component LSL2 
        generic(NBIT: integer :=2*NBIT);
        port(
            A : in std_logic_vector(NBIT-1 downto 0);
            Y : out std_logic_vector(NBIT-1 downto 0)
        );
    end component;
    
-- mux 31 : used to select either 0, A, 2A
    component MUX31_GENERIC 
        generic (NBIT : integer := NBIT;
                            DELAY_MUX : time := tp_mux);
        port (
                A : in std_logic_vector(NBIT - 1 downto 0);
                B : in std_logic_vector(NBIT - 1 downto 0);
            C : in std_logic_vector(NBIT - 1 downto 0);
            SEL : in std_logic_vector(1 downto 0);
            Y : out std_logic_vector(NBIT - 1 downto 0));
    end component;

-- encoder  : used to generate 2 signals:
--      -MAG : used as selection signal of the mux31(magnitude)
--      -SIGN: used to select the sign(A, -A, ...)
    component encoder 
        port(
            S_IN :  in std_logic_vector(2 downto 0);
            MAG  :  out std_logic_vector(1 downto 0);
            SIGN :  out std_logic   
        );
    end component;
    component XOR_2 
        port(
            A : in std_logic;
            B : in std_logic;
            Y : out std_logic
        );
    end component;

    -- ADDER : used to compute partial products, a simple carry select is used
    component CARRY_SEL_ADD
    generic(NBIT : integer := numBit;
        NBLOCKS : integer := numBit/numBit_block);
    port(
        A : in std_logic_vector(NBIT-1 downto 0);
        B : in std_logic_vector(NBIT-1 downto 0);
        Ci : in std_logic;
        S : out std_logic_vector(NBIT-1 downto 0);
        Co : out std_logic
    );
    end component;

    -- Generic pipeline register, used between Booth layers
    component REG_PIPE
        generic(NBIT : integer := NBIT);
        port(
            CLK : in std_logic;
            RST : in std_logic;
            EN  : in std_logic;
            D   : in std_logic_vector(NBIT-1 downto 0);
            Q   : out std_logic_vector(NBIT-1 downto 0)
        );
    end component;

-- SIGNALS 
-- signals that propagate the partial products, as wide as the output operand (2*NBIT) and as deep as levels of the multiplier (NBIT/2) ((ToDo: the actual layers are 1 less then the depth declared here, but this should not be a problem as non connected signals will be ignored))
type SignalVector is array (0 to NBIT/2 - 1) of std_logic_vector(2*NBIT-1 downto 0);
  signal P : SignalVector;   -- REGISTERED matrix of Partial products (output of pipeline register for each layer)
  signal A_2 : SignalVector;     -- REGISTERED matrix carrying the shifted-by-2 version of A (output of pipeline register for each layer)
  signal A_4 : SignalVector;     -- REGISTERED matrix carrying the shifted-by-4 version of A (output of pipeline register for each layer)
  signal MUX_OUT : SignalVector; -- matrix carrying the output of mux31 (combinational, within a stage)
  signal XOR_OUT : SignalVector; -- matrix, connected to xor (combinational, within a stage)

  -- combinational (pre-register) versions of the signals above, produced within each stage
  signal P_comb   : SignalVector;
  signal A_2_comb : SignalVector;
  signal A_4_comb : SignalVector;

type SignalVector_2 is array (0 to NBIT/2 - 1) of std_logic_vector(1 downto 0);
  signal SEL_Enc : SignalVector_2;  -- selection signal from encoder to mux

-- B, delayed/pipelined so that layer i's encoder reads a version of B
-- that has traveled through the same number of pipeline stages as the
-- partial product / shifted-A signals it is combined with.
type BVector is array (0 to NBIT/2 - 2) of std_logic_vector(NBIT-1 downto 0);
  signal B_pipe : BVector;

signal SIGN_partial : std_logic_vector(NBIT/2-1 downto 0); 
signal zero_extended : std_logic_vector(2*NBIT-1 downto 0); -- Zero signal as wide as the output, just a generic way to have a 0 with NBIT*2 width
signal A_extended : std_logic_vector(2*NBIT-1 downto 0); -- A represented on a signal as wide as the output
signal B0_slice : std_logic_vector(2 downto 0); -- Slice of B on just 3 bits, this is supposed to be used as input ton a single encoder
--signal RES_tmp : std_logic_vector(2*NBIT-1 downto 0);        

---------------------------------------------------------------------------------------------
-- Validity pipeline: mirrors P/A_2/A_4 stage by stage, carrying
-- a single bit that says "there is a valid multiplication result
-- flowing through this stage". Its last stage (DONE) is therefore
-- always aligned with RES, regardless of NBIT.
------------------------------------------------------------------------------------------
signal V      : std_logic_vector(0 to NBIT/2 - 1); -- REGISTERED validity, stage by stage
signal V_comb : std_logic_vector(0 to NBIT/2 - 1); -- combinational (pre-register) validity

-- Internal FSM controlling the pipeline registers' enable
type mul_state_t is (IDLE, BUSY_ST);
signal state, next_state : mul_state_t;
signal reg_en   : std_logic; -- actual enable fed to every REG_PIPE
signal busy_int : std_logic; -- combinational '1' when state = BUSY_ST

begin 
zero_extended <= (others => '0'); -- Set the zero vector to zero
A_extended <= std_logic_vector(resize(signed(A), 2*NBIT)); -- Assign the extend version of A to the signal
B0_slice <= B(1 downto 0) & '0'; 

---------------------------------------------------------------------------------------
-- Internal FSM: IDLE while no multiplication is in flight,
-- BUSY_ST from the cycle after START until the result comes out.
-- reg_en is what actually clocks every REG_PIPE in the datapath:
-- it is asserted the cycle START arrives and stays asserted while
-- BUSY_ST, always ANDed with the external EN so an unrelated stall
-- coming from elsewhere in the pipeline still freezes the multiplier.
---------------------------------------------------------------------------------------
busy_int <= '1' when state = BUSY_ST else '0';
reg_en   <= EN and (START or busy_int or V(NBIT/2 - 1));

BUSY <= busy_int;
DONE <= V(NBIT/2 - 1);

FSM_STATE_REG : process(CLK, RST)
begin
    if RST = '0' then
        state <= IDLE;
    elsif rising_edge(CLK) then
        if EN = '1' then
            state <= next_state;
        end if;
    end if;
end process FSM_STATE_REG;

FSM_NEXT_STATE : process(state, START, V)
begin
    next_state <= state;
    case state is
        when IDLE =>
            if START = '1' then
                next_state <= BUSY_ST;
            end if;
        when BUSY_ST =>
            if V(NBIT/2 - 1) = '1' then -- last stage just became valid: finishing this cycle
                next_state <= IDLE;     -- Torna SEMPRE in IDLE al termine, anche se START e' ancora '1'
            end if;
    end case;
end process FSM_NEXT_STATE;

BLOCK_CONN : for i in 0  to NBIT/2 -1 generate -- Iterate through layers of the multiplier
    FIRST_LAYER : if (i = 0) generate -- First layer is different: the first input of the adder does not come from partial products, but from another mux

        ENCODER_INST_0 : encoder
            port map(
                S_IN => B0_slice,
                MAG  => SEL_Enc(0),
                SIGN => SIGN_partial(0) 
            );

        LSL_INST_0 : LSL
            generic map (NBIT => 2* NBIT)
            port map (
                A => A_extended,
                Y => A_2_comb(0)
            );

        MUX_INST_0 : MUX31_GENERIC
            generic map  (NBIT => 2*NBIT )
            port map (
                    A   => zero_extended,
                    B   => A_extended,
                    C   => A_2_comb(0),
                    SEL     => SEL_Enc(0),
                    Y   => MUX_OUT(0)
            );
        A_4_comb(0) <= A_extended;

-- an XOR layer between the output of the mux and the SIGN signal from the Encoder
-- is used to select the correct sign
        XOR_LAYER_0 : for j in 0 to 2*NBIT-1 generate
            XOR_INST_0: XOR_2
                port map(
                    A => SIGN_partial(0),
                    B => MUX_OUT(0)(j),
                    Y => XOR_OUT(0)(j)
                );  
        end generate XOR_LAYER_0;
        
        SUM_INST_0 : CARRY_SEL_ADD
            generic map(NBIT => 2*NBIT,
                                NBLOCKS => 2*NBIT/numBit_block)
                        port map(
                A => XOR_OUT(i),
                B => zero_extended,
                Ci => SIGN_partial(0),
                S => P_comb(0),
                Co => open
            );

        -- pipeline registers closing stage 0
        REG_P_0 : REG_PIPE
            generic map (
                NBIT => 2*NBIT)
            port map (
                CLK => CLK,
                RST => RST,
                EN => reg_en, 
                D => P_comb(0),
                Q => P(0));

        REG_A2_0 : REG_PIPE
            generic map (
                NBIT => 2*NBIT)
            port map (
                CLK => CLK, 
                RST => RST, 
                EN => reg_en, 
                D => A_2_comb(0), 
                Q => A_2(0));

        REG_A4_0 : REG_PIPE
            generic map (NBIT => 2*NBIT)
            port map (CLK => CLK, 
            RST => RST, 
            EN => reg_en, 
            D => A_4_comb(0), 
            Q => A_4(0));

        -- delay B so that stage 1's encoder receives it aligned with P(0)/A_2(0)/A_4(0)
        REG_B_0 : REG_PIPE
            generic map (
                NBIT => NBIT)
            port map (
                CLK => CLK, 
                RST => RST, 
                EN => reg_en, 
                D => B, 
                Q => B_pipe(0));

        -- validity pipeline, stage 0: latches START solo all'inizio (in IDLE)
        REG_V_0 : REG_PIPE
            generic map (
                NBIT => 1)
            port map (
                CLK => CLK,
                RST => RST,
                EN => reg_en,
                D(0) => V_comb(0),
                Q(0) => V(0));

        -- Inseriamo '1' in V_comb(0) SOLO se siamo in IDLE e START e' '1'
        V_comb(0) <= START when state = IDLE else '0';

    end generate FIRST_LAYER;
    MORE_LAYERS : if (i/=0) generate -- For other cases use a regular structure
        ENCODER_INST_i : encoder
            port map(
                S_IN => B_pipe(i-1)(i*2+1 downto i*2-1),
                MAG  => SEL_Enc(i),
                SIGN => SIGN_partial(i) 
            );

        -- Each layer takes previously shifted result, and shifts it further 
        LSL_INST_i : LSL2
            generic map (NBIT => 2* NBIT)
            port map (
                A => A_2(i-1),
                Y => A_2_comb(i)
            );

        LSL2_INST_i : LSL2
            generic map (NBIT => 2* NBIT)
            port map (
                A => A_4(i-1),
                Y => A_4_comb(i)
            );
        -- Select one of the operands
        MUX_INST_i : MUX31_GENERIC
            generic map  (NBIT => 2*NBIT )
            port map (
                    A   => zero_extended,
                    B   => A_4_comb(i),
                    C   => A_2_comb(i),
                    SEL     => SEL_Enc(i),
                    Y   => MUX_OUT(i)
            );
        -- Sign selection
        XOR_LAYER_i : for a in 0 to 2*NBIT-1 generate
            XOR_INST: XOR_2
                port map(
                    A => SIGN_partial(i),
                    B => MUX_OUT(i)(a),
                    Y => XOR_OUT(i)(a)
                );  
        end generate XOR_LAYER_i;
        -- Perform addition
        SUM_INST_i : CARRY_SEL_ADD 
            generic map(NBIT => 2*NBIT,
                                NBLOCKS => 2*NBIT/numBit_block)
                        port map(
                A => XOR_OUT(i),
                B => P(i-1),
                Ci => SIGN_partial(i),
                S => P_comb(i),
                Co => open
            );

        -- pipeline registers closing stage i
        REG_P_i : REG_PIPE
            generic map (
                NBIT => 2*NBIT)
            port map (
                CLK => CLK, 
                RST => RST, 
                EN => reg_en, 
                D => P_comb(i), 
                Q => P(i));

        REG_A2_i : REG_PIPE
            generic map (
                NBIT => 2*NBIT)
            port map (
                CLK => CLK, 
                RST => RST, 
                EN => reg_en, 
                D => A_2_comb(i), 
                Q => A_2(i));

        REG_A4_i : REG_PIPE
            generic map (
                NBIT => 2*NBIT)
            port map (
                CLK => CLK,
                RST => RST, 
                EN => reg_en, 
                D => A_4_comb(i), 
                Q => A_4(i));

        -- only propagate B further if a following stage still needs it
        NOT_LAST : if (i < NBIT/2 - 1) generate
            REG_B_i : REG_PIPE
                generic map (
                    NBIT => NBIT)
                port map (
                    CLK => CLK, 
                    RST => RST, 
                    EN => reg_en, 
                    D => B_pipe(i-1), 
                    Q => B_pipe(i));
        end generate NOT_LAST;

        -- validity pipeline, stage i: just shifts the bit from the previous stage
        REG_V_i : REG_PIPE
            generic map (
                NBIT => 1)
            port map (
                CLK => CLK,
                RST => RST,
                EN => reg_en,
                D(0) => V_comb(i),
                Q(0) => V(i));

        V_comb(i) <= V(i-1);

    end generate MORE_LAYERS;
end generate BLOCK_CONN;

            RES <= P(NBIT/2-1)(NBIT-1 downto 0); -- Low 32 bits of the result
           
end architecture;